namespace Api.Models;

/// <summary>The lifecycle status of an order.</summary>
public enum OrderStatus
{
    Pending,
    Processing,
    Shipped,
    Delivered,
    Cancelled
}

namespace Api.Models;

/// <summary>Represents an order returned by the API.</summary>
public sealed record OrderResponse(
    int Id,
    int CustomerId,
    DateTimeOffset PlacedAt,
    decimal TotalAmount,
    OrderStatus Status);

using System.ComponentModel.DataAnnotations;

namespace Api.Models;

/// <summary>Payload for creating a new order.</summary>
public sealed record CreateOrderRequest
{
    [Required]
    public required int CustomerId { get; init; }

    [Required]
    public required DateTimeOffset PlacedAt { get; init; }

    [Range(0.01, (double)decimal.MaxValue)]
    public required decimal TotalAmount { get; init; }

    [Required]
    public required OrderStatus Status { get; init; }
}

using Api.Models;

namespace Api.Services;

public interface IOrderService
{
    Task<IReadOnlyList<OrderResponse>> GetAllAsync(CancellationToken ct);
    Task<OrderResponse?> GetByIdAsync(int id, CancellationToken ct);
    Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken ct);
}

using Api.Models;

namespace Api.Services;

public sealed class OrderService : IOrderService
{
    private readonly List<OrderResponse> _orders = [];
    private int _nextId = 1;

    public Task<IReadOnlyList<OrderResponse>> GetAllAsync(CancellationToken ct)
    {
        return Task.FromResult<IReadOnlyList<OrderResponse>>(_orders.AsReadOnly());
    }

    public Task<OrderResponse?> GetByIdAsync(int id, CancellationToken ct)
    {
        var order = _orders.Find(o => o.Id == id);
        return Task.FromResult(order);
    }

    public Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken ct)
    {
        var order = new OrderResponse(
            _nextId++,
            request.CustomerId,
            request.PlacedAt,
            request.TotalAmount,
            request.Status);

        _orders.Add(order);
        return Task.FromResult(order);
    }
}

using Api.Models;
using Api.Services;
using Microsoft.AspNetCore.Mvc;

namespace Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class OrdersController(IOrderService service) : ControllerBase
{
    /// <summary>Returns all orders.</summary>
    [HttpGet]
    [ProducesResponseType<List<OrderResponse>>(StatusCodes.Status200OK)]
    public async Task<ActionResult<List<OrderResponse>>> GetAll(CancellationToken cancellationToken)
    {
        var orders = await service.GetAllAsync(cancellationToken);
        return Ok(orders);
    }

    /// <summary>Returns a single order by ID.</summary>
    [HttpGet("{id:int}")]
    [ProducesResponseType<OrderResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<OrderResponse>> GetById(int id, CancellationToken cancellationToken)
    {
        var order = await service.GetByIdAsync(id, cancellationToken);
        return order is null ? NotFound() : Ok(order);
    }

    /// <summary>Creates a new order.</summary>
    [HttpPost]
    [ProducesResponseType<OrderResponse>(StatusCodes.Status201Created)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<ActionResult<OrderResponse>> Create(
        CreateOrderRequest request, CancellationToken cancellationToken)
    {
        var order = await service.CreateAsync(request, cancellationToken);
        return CreatedAtAction(nameof(GetById), new { id = order.Id }, order);
    }
}

